// Minute-of-day helpers for notification scheduling.
export const MINUTES_PER_DAY = 1440;

export interface QuietWindow {
  readonly start: number;
  readonly end: number;
}

export interface DeliveryPrefs {
  readonly quiet: QuietWindow | null;
  readonly bypass: readonly string[];
}

export interface Notice {
  readonly senderId: string;
  readonly urgent: boolean;
}

export interface DeliveryPlan {
  readonly deferred: boolean;
  readonly deliverIn: number;
}

export function isValidMinute(value: number): boolean {
  return Number.isInteger(value) && value >= 0 && value < MINUTES_PER_DAY;
}

function requireMinute(name: string, value: number): void {
  if (!isValidMinute(value)) throw new RangeError(`${name} must be an integer minute in 0..1439`);
}

/** Minutes from `from` forward to `to`, counting across midnight: always 0..1439. */
function minutesUntil(from: number, to: number): number {
  return (to - from + MINUTES_PER_DAY) % MINUTES_PER_DAY;
}

/**
 * Rotates the day so that the window starts at minute 0. A minute is then inside the window exactly when its
 * offset from the start is smaller than the window's length. A window with start === end has length 0 and so
 * contains no minute; a window that runs past midnight simply has a length that crosses it.
 */
function inQuietWindow(window: QuietWindow, minute: number): boolean {
  const length = minutesUntil(window.start, window.end);
  const offset = minutesUntil(window.start, minute);
  return offset < length;
}

function isBypassed(prefs: DeliveryPrefs, notice: Notice): boolean {
  return notice.urgent && prefs.bypass.includes(notice.senderId);
}

export function planDelivery(prefs: DeliveryPrefs, notice: Notice, minuteOfDay: number): DeliveryPlan {
  requireMinute("minuteOfDay", minuteOfDay);
  const quiet = prefs.quiet;
  if (quiet !== null) {
    requireMinute("quiet.start", quiet.start);
    requireMinute("quiet.end", quiet.end);
  }
  if (quiet === null || isBypassed(prefs, notice) || !inQuietWindow(quiet, minuteOfDay)) {
    return { deferred: false, deliverIn: 0 };
  }
  return { deferred: true, deliverIn: minutesUntil(minuteOfDay, quiet.end) };
}
